"""
The abstraction of the state of an UI element entity
"""
import squishtest as sq
from interops.libraries.squish_actions.common import find_object, clear_text, set_text, click_item
from typing import Union, Optional
import ctypes
from ctypes import wintypes
from interops.libraries.miscellaneous import remote_py_functions

def get_style(hwnd) -> int:
    '''
    Function to get the style of a control (e.g. button)

    :param: hwnd (wintypes.HWND): the hwnd of the control

    :return: the style of the control
    '''
    if "ctypes" not in locals():
        import ctypes
    GWL_STYLE = -16
    user32 = ctypes.windll.user32
    style = user32.GetWindowLongW(hwnd, GWL_STYLE)
    return style

def get_style_remote(hwnd) -> int:
    '''
    Remote executing of get_style.

    :param: hwnd (wintypes.HWND): the hwnd of the control

    :return: the style of the control
    '''
    ret = remote_py_functions.execute_remote_py_function(get_style, [hwnd])
    return int(str(ret).strip("\n "))

def has_autocheckbox_style(hwnd:wintypes.HWND) -> bool:
    '''
    Check if a control has auto checkbox style

    :param: hwnd (wintypes.HWND): the hwnd of the control

    :return: true if it has, false otherwise
    '''
    BS_AUTOCHECKBOX = 0x00000003
    style = get_style_remote(hwnd)
    return (style & BS_AUTOCHECKBOX) == BS_AUTOCHECKBOX

def is_checked(hwnd)->bool:
    '''
    Function to check if the control (e.g. button) is checked

    :param: hwnd: the hwnd of the control

    :return: True if it is checked, False otherwise
    '''
    if "ctypes" not in locals():
        import ctypes
    BM_GETCHECK = 0x00F0
    BST_CHECKED = 0x0001
    user32 = ctypes.windll.user32
    result = user32.SendMessageW(hwnd, BM_GETCHECK, 0, 0)
    checked = (result == BST_CHECKED)
    return checked

def is_checked_remote(hwnd:wintypes.HWND) ->bool:
    '''
    Remote executing of is_checked fuction

    :param: hwnd (wintypes.HWND): the hwnd of the control

    :return: True if it is checked, False otherwise
    '''
    ret = remote_py_functions.execute_remote_py_function(is_checked, [hwnd])
    return str(ret).strip("\n ") == str(True)

def get_value(obj_id: Union[int,dict,object]) -> Union[bool, str]:
    '''
    Get the value of the UI element by given id/mapped object

    :param: obj_id (int, dict, or object), the id (or id data object) of the UI element
    :return: the value of the UI element.
    '''
    if isinstance(obj_id, int):
        obj_id = {"id": obj_id}
    obj = sq.waitForObjectExists(obj_id,10000) # type: ignore
    if hasattr(obj, "checked"):
        return obj.checked # type: ignore
    elif hasattr(obj, "nativeObject") and (hasattr(obj.nativeObject, "Checked") or hasattr(obj.nativeObject, "IsChecked")):
        return obj.nativeObject.Checked if hasattr(obj.nativeObject, "Checked") else obj.nativeObject.IsChecked
    elif hasattr(obj, "hwnd") and has_autocheckbox_style(obj.hwnd): # type: ignore
        return is_checked_remote(obj.hwnd) # type: objignore
    elif hasattr(obj, "text"):
        return obj.text # type: ignore
    elif hasattr(obj, "nativeObject") and hasattr(obj.nativeObject, "Text"): # type: ignore
        return obj.nativeObject.Text # type: ignore
    else:
        raise TypeError("Unsupported object type.")

def set_value(obj_id: Union[int,dict,object], value):
    '''
    Set specified value to the UI element given by its id/mapped object.

    :params: obj_id (int, dict, or object), the id (or id data object) of the UI element
             value, the value to be set, can be int, bool or str.
    '''
    if isinstance(obj_id, int):
        obj_id = {"id": obj_id}
    obj = sq.waitForObjectExists(obj_id, 10000) # type: ignore
    if obj is None:
        raise Exception("The control is unavailable.")

    if hasattr(obj, "checked") or (hasattr(obj, "nativeObject") and (hasattr(obj.nativeObject, "Checked") or (hasattr(obj.nativeObject, "IsChecked") )) ): # type: ignore
        if isinstance(value, bool):
            if ( (hasattr(obj, "checked") and obj.checked != value) or # type: ignore
                (hasattr(obj, "nativeObject") and
                   ( ( (hasattr(obj.nativeObject, "Checked") and obj.nativeObject.Checked != value) ) or # type: ignore
                   ( (hasattr(obj.nativeObject, "IsChecked") and obj.nativeObject.IsChecked != value ) ) )
                ) ): # type: ignore
                if obj.enabled:
                    sq.mouseMove(obj) # type: ignore
                    sq.mouseClick(obj, obj.width/8, obj.height/2, sq.MouseButton.LeftButton) # type: ignore
                else:
                    raise Exception("Control must be enabled to change its state")
        else:
            raise ValueError("Checked value must be a boolean.")
    elif hasattr(obj, "hwnd") and isinstance(value, bool) and has_autocheckbox_style(obj.hwnd): # type: ignore
        if is_checked_remote(obj.hwnd) != value: # type: ignore
            if obj.enabled:
                sq.mouseMove(obj) # type: ignore
                sq.mouseClick(obj) # type: ignore
            else:
                raise Exception("Control must be enabled to change its state")
    elif hasattr(obj, "text") or (hasattr(obj, "nativeObject") and hasattr(obj.nativeObject, "Text")): # type: ignore
        try:
            if hasattr(obj, "text"):
                if  obj.text != str(value):
                    if obj.enabled:
                        set_text(obj, value if isinstance(value, str) else str(value), False)
                    else:
                        raise Exception(f"Failed to set value to {value}. Control must be enabled.")
            elif hasattr(obj, "nativeObject") and hasattr(obj.nativeObject, "Text"):
                if obj.nativeObject.Text != str(value):
                    if obj.enabled:
                        set_text(obj, value if isinstance(value, str) else str(value), False)
                    else:
                        raise Exception(f"Failed to set value to {value}. Control must be enabled.")
        except Exception as e:
            print(str(e))
    else:
        raise TypeError("Unsupported object type.")

class State:
    """
    Class to model the state(on, off or value) of UI element, e.g., CheckBox, RadioButton, Edit (and some list control)

    Use the id/object map of the UI element to locate and access it.

    To get or set value, use value property and setter, for example

    s = State(14021)   # s = State({"id": 14021, "type": "Edit"})

    val = s.value

    s.value = True

    Note: init_value is default to None. Normally, you don't have to change it for a control whose value may be of bool or str or int.
    However, if init_value matters for some controls, it need to be updated accordingly, especially if the value is int, which would be otherwise
    treated as bool or str as get_value gets the value of type str or bool. Also in case, you may need to know the actual init_value, so you can
    get it before setter is called by s._value.

    """
    def __init__(self, id: Union[int,dict,object], init_value: Optional[Union[bool,str,int]]=None):
        self.id = id
        self._value = init_value

    @property
    def value(self):
        val = get_value(self.id)
        self._value = int(val) if type(self._value) is int else val
        return self._value

    @value.setter
    def value(self, new_value):
        set_value(self.id, new_value)
        self._value = new_value
